  'terms.services.item2':             { ar:'شحن تطبيقات الجوال', en:'Mobile app top-ups', tr:'Mobil uygulama şarjı', fr:'Recharge d\'applications mobiles', es:'Recarga de aplicaciones móviles', pt:'Recarga de aplicativos móveis', fa:'شارژ اپلیکیشن‌های موبایل', ru:'Пополнение мобильных приложений', de:'Mobile App-Aufladungen', id:'Top-up aplikasi mobile', ku:'شارژکردنی ئەپلیکەیشنی مۆبایل' },
