  'terms.services.item4':             { ar:'إعادة شحن الرصيد الهاتفي', en:'Phone credit recharge', tr:'Telefon kredisi yenileme', fr:'Rechargement de crédit téléphonique', es:'Recarga de crédito telefónico', pt:'Recarga de crédito telefônico', fa:'شارژ اعتبار تلفن', ru:'Пополнение телефонного кредита', de:'Telefonkredit-Aufladung', id:'Isi ulang kredit telepon', ku:'نوێکردنەوەی کریدیتی تەلەفۆن' },
  'terms.services.note':              { ar:'الأسعار قابلة للتغيير دون إشعار مسبق.', en:'Prices are subject to change without prior notice.', tr:'Fiyatlar önceden bildirim yapılmaksızın değiştirilebilir.', fr:'Les prix peuvent changer sans préavis.', es:'Los precios pueden cambiar sin previo aviso.', pt:'Os preços estão sujeitos a alterações sem aviso prévio.', fa:'قیمت‌ها ممکن است بدون اطلاع قبلی تغییر کنند.', ru:'Цены могут меняться без предварительного уведомления.', de:'Preise können sich ohne vorherige Ankündigung ändern.', id:'Harga dapat berubah tanpa pemberitahuan sebelumnya.', ku:'نرخەکان دەتوانن بگۆڕن بەبێ ئاگادارکردنەوەی پێشوەخت.' },
  'terms.refund.title':               { ar:'سياسة الاسترداد', en:'Refund Policy', tr:'İade Politikası', fr:'Politique de remboursement', es:'Política de reembolso', pt:'Política de reembolso', fa:'سیاست بازپرداخت', ru:'Политика возврата', de:'Rückerstattungsrichtlinie', id:'Kebijakan Pengembalian Dana', ku:'سیاسەتی گەڕاندنەوەی پارە' },
  'terms.refund.highlight':           { ar:'لا يوجد استرداد للأموال إلا في حالة وجود خطأ تقني من طرفنا.', en:'No refunds will be issued except in case of a technical error on our part.', tr:'Bizim tarafımızdan kaynaklanan teknik bir hata olmadıkça para iadesi yapılmayacaktır.', fr:'Aucun remboursement ne sera effectué sauf en cas d\'erreur technique de notre part.', es:'No se realizarán reembolsos excepto en caso de error técnico de nuestra parte.', pt:'Não haverá reembolsos exceto em caso de erro técnico de nossa parte.', fa:'هیچ بازپرداختی انجام نمی‌شود مگر در صورت خطای فنی از طرف ما.', ru:'Возврат средств не производится, за исключением случаев технической ошибки с нашей стороны.', de:'Es werden keine Rückerstattungen gewährt, außer bei einem technischen Fehler unsererseits.', id:'Tidak ada pengembalian dana kecuali dalam kasus kesalahan teknis dari pihak kami.', ku:'هیچ گەڕاندنەوەی پارەیەک نییە مەگەر ئەگەر هەڵەیەکی تەکنیکی لە لایەنمانەوە هەبێت.' },
